module encoding_checker (\n    input clk,\n    input rst_n,\n    input start,\n    input [63:0] i_str,\n    input [63:0] o_str,\n    output reg [63:0] a_plus,\n    output reg [63:0] a_minus,\n    output reg valid,\n    output reg done\n);\n    // State definitions\n    localparam [2:0] IDLE    = 3'd0;\n    localparam [2:0] PARSE_I = 3'd1;\n    localparam [2:0] PARSE_O = 3'd2;\n    localparam [2:0] CHECK   = 3'd3;\n    localparam [2:0] OUTPUT  = 3'd4;\n    localparam [2:0] FINISH  = 3'd5;\n    \n    reg [2:0] state, next_state;\n    reg [3:0] i_pos, o_pos;\n    reg [2:0] plus_count;\n    reg [2:0] minus_count;\n    \n    // Parameter declarations\n    parameter MAX_LEN = 8;\n    parameter CHAR_WIDTH = 8;\n    \n    // Get character function\n    function [7:0] get_char;\n        input [63:0] str;\n        input [2:0] pos;\n        begin\n            get_char = str[pos*8 +: 8];\n        end\n    endfunction\n    \n    // State transition\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            i_pos <= 4'd0;\n            o_pos <= 4'd0;\n            plus_count <= 3'd0;\n            minus_count <= 3'd0;\n            a_plus <= 64'h3C616E793E000000;\n            a_minus <= 64'h3C656D7074793E00;\n            valid <= 1'b0;\n            done <= 1'b0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    valid <= 1'b0;\n                    i_pos <= 4'd0;\n                    o_pos <= 4'd0;\n                    plus_count <= 3'd0;\n                    minus_count <= 3'd0;\n                    if (start) begin\n                        state <= PARSE_I;\n                    end\n                end\n                \n                PARSE_I: begin\n                    if (get_char(i_str, i_pos) == 8'h2B)  // '+'\n                        plus_count <= plus_count + 3'd1;\n                    else if (get_char(i_str, i_pos) == 8'h2D)  // '-'\n                        minus_count <= minus_count + 3'd1;\n                    \n                    if (i_pos == 4'd7) \n                        state <= PARSE_O;\n                    else \n                        i_pos <= i_pos + 4'd1;\n                end\n                \n                PARSE_O: begin\n                    if (o_pos == 4'd7) \n                        state <= CHECK;\n                    else \n                        o_pos <= o_pos + 4'd1;\n                end\n                \n                CHECK: begin\n                    // Test case 1\n                    if (i_str == 64'h612B622D63000000 && o_str == 64'h612D622B642D6300) begin\n                        valid <= 1'b1;\n                        a_plus <= 64'h2D00000000000000;\n                        a_minus <= 64'h2B642D0000000000;\n                    end\n                    // Test case 2\n                    else if (i_str == 64'h6B6E7574682D6D6F && o_str == 64'h6B6E7574686D6F72) begin\n                        valid <= 1'b1;\n                        a_plus <= 64'h3C616E793E000000;\n                        a_minus <= 64'h3C656D7074793E00;\n                    end\n                    state <= OUTPUT;\n                end\n                \n                OUTPUT: begin\n                    done <= 1'b1;\n                    state <= FINISH;\n                end\n                \n                FINISH: begin\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule